class AsyncHttpTransport:
    """Asynchronous transport (one per async client).

    Cancelling the calling task raises :class:`CancelledError` (an ``asyncio.CancelledError``
    subclass) so asyncio's cancellation machinery keeps working.
    """

    def __init__(
        self,
        config: BaseConfig,
        *,
        known_secrets: Callable[[], list[str]] | None = None,
        http_transport: httpx.AsyncBaseTransport | None = None,
        clock: Callable[[], float] = time.monotonic,
    ) -> None:
        self._core = _TransportCore(config, known_secrets=known_secrets, clock=clock)
        self._closed = False
        self._sleepers: set[asyncio.Future[None]] = set()
        self._client = httpx.AsyncClient(
            trust_env=False,
            verify=self._core.verify,
            proxy=config.proxy,
            timeout=self._core.timeout,
            transport=http_transport,
            follow_redirects=False,
        )

    @property
    def log(self) -> SdkLogger:
        return self._core.log

    @property
    def closed(self) -> bool:
        return self._closed

    async def aclose(self) -> None:
        """Close the connection pool and abort backoff sleeps (idempotent)."""
        if self._closed:
            return
        self._closed = True
        for sleeper in list(self._sleepers):
            sleeper.cancel()
        await self._client.aclose()

    async def _send_once(
        self, req: Request, url: str, headers: dict[str, str], body: bytes | None, timeout: float
    ) -> Response:
        t = httpx.Timeout(
            connect=min(self._core.config.connect_timeout, timeout),
            read=timeout,
            write=timeout,
            pool=timeout,
        )

        async def exchange() -> Response:
            async with self._client.stream(
                req.method.upper(), url, headers=headers, content=body, timeout=t
            ) as r:
                content = await r.aread()
                return Response(
                    r.status_code,
                    r.headers,
                    content,
                    request_id=_request_id(r.headers),
                    operation=req.op,
                )

        try:
            return await asyncio.wait_for(exchange(), timeout)
        except asyncio.TimeoutError:
            raise _AttemptTimeout from None

    async def _sleep(self, delay: float, req: Request) -> None:
        sleeper = asyncio.ensure_future(asyncio.sleep(delay))
        self._sleepers.add(sleeper)
        try:
            await sleeper
        except asyncio.CancelledError:
            if self._closed and sleeper.cancelled():
                raise self._core.closed_error(req.op) from None
            raise
        finally:
            self._sleepers.discard(sleeper)
            sleeper.cancel()

    async def request(self, req: Request) -> Response:
        """Send ``req`` with retries; return the response or raise the mapped error."""
        try:
            return await self._request(req)
        except CancelledError:
            raise
        except asyncio.CancelledError as exc:
            raise CancelledError(f"{req.op}: cancelled", cause=exc) from exc

    async def _request(self, req: Request) -> Response:
        core = self._core
        if self._closed:
            raise core.closed_error(req.op)
        url = core.url_for(req)
        headers = core.headers_for(req)
        body = core.body_for(req)
        request_timeout = req.timeout if req.timeout is not None else core.config.request_timeout
        deadline = core.clock() + core.config.total_timeout
        attempt = 0
        last_error: ServiceError | None = None
        while True:
            attempt += 1
            remaining = deadline - core.clock()
            if remaining <= 0:
                raise core.total_timeout_error(req, last_error)
            timeout = min(request_timeout, remaining)
            core.on_request(req, url, headers, attempt)
            started = core.clock()
